import type { CanonicalRide, Row } from '../harness';

const fix = (
  elapsedSeconds: number,
  timestamp: string,
  producer: 'phone' | 'watch',
  producerSequence: number,
  clockEpoch: string,
  values: Row,
): Row => ({ elapsedSeconds, timestamp, producer, producerSequence, clockEpoch, distanceBarrier: 0, ...values });

const event = (
  elapsedSeconds: number,
  timestamp: string,
  producerSequence: number,
  action: string,
  timerSeconds: number,
) => ({
  elapsedSeconds,
  timestamp,
  producer: 'watch',
  producerSequence,
  clockEpoch: 'w-1',
  action,
  timerSeconds,
  interrupted: 0,
});

